# pebble_studio_sim.py — Pebble Studio simulated location & weather for pypkjs.
#
# WHY: weather watchfaces fetch real weather over the network via
# navigator.geolocation + XMLHttpRequest, both of which funnel through `requests`
# inside the bundled pypkjs. With no phone (and dead hardcoded API keys) the fetch
# fails and the watch shows a sentinel (e.g. an "unknown condition" placeholder).
#
# This module, installed from sitecustomize when PEBBLE_SIM_ENV_FILE is set, wraps
# requests.Session.send so calls to known weather hosts return synthetic JSON built
# from a control file, calls to api.ipify.org return a canned IP (offline geo), and
# patches pygeoip so getCurrentPosition resolves to the configured lat/lon. Every
# branch is guarded so a failure falls back to real behavior and never breaks the
# emulator.
import json
import os
import time
from urllib.parse import urlparse

# category -> (OpenWeatherMap weather[].id, WeatherAPI condition.code)
# Codes chosen so a watchface's own condition-code mapping resolves them to the
# intended internal icon category.
CONDITIONS = {
    "clear":   (800, 1000),
    "partly":  (801, 1003),
    "cloudy":  (804, 1006),
    "fog":     (741, 1135),
    "drizzle": (301, 1153),
    "rain":    (501, 1189),
    "sleet":   (612, 1207),
    "snow":    (601, 1213),
    "thunder": (211, 1087),
    "wind":    (905, 1117),
}

DEFAULTS = {
    "enabled": True,
    "location": {"lat": 33.6846, "lon": -117.8265, "name": "Irvine"},
    "weather": {"condition": "clear", "tempC": 20.56, "isDay": True},
    "units": "F",
}

_state = {"mtime": None, "cfg": None}


def _read(env_file):
    """Absent/unreadable/malformed -> DEFAULTS (enabled). Cached by mtime so a
    long-lived process re-reads only when the UI rewrites the file."""
    try:
        st = os.stat(env_file)
    except OSError:
        return DEFAULTS
    if st.st_mtime == _state["mtime"] and _state["cfg"] is not None:
        return _state["cfg"]
    try:
        with open(env_file, "r", encoding="utf-8") as f:
            cfg = json.load(f)
    except (OSError, ValueError):
        return DEFAULTS
    _state["mtime"] = st.st_mtime
    _state["cfg"] = cfg
    return cfg


def _to_f(c):
    return round(c * 9.0 / 5.0 + 32)


# category -> (OpenWeatherMap main, description, icon number). The icon gets a
# "d"/"n" suffix from isDay. ids come from CONDITIONS above.
OWM_TEXT = {
    "clear":   ("Clear", "clear sky", "01"),
    "partly":  ("Clouds", "few clouds", "02"),
    "cloudy":  ("Clouds", "overcast clouds", "04"),
    "fog":     ("Fog", "fog", "50"),
    "drizzle": ("Drizzle", "drizzle", "09"),
    "rain":    ("Rain", "moderate rain", "10"),
    "sleet":   ("Rain", "light shower sleet", "13"),
    "snow":    ("Snow", "snow", "13"),
    "thunder": ("Thunderstorm", "thunderstorm", "11"),
    "wind":    ("Clear", "windy", "01"),
}


def _owm_weather(cfg):
    """weather[] array for the simulated condition."""
    w = cfg.get("weather", DEFAULTS["weather"])
    cond = w.get("condition") if w.get("condition") in CONDITIONS else "clear"
    main, desc, icon = OWM_TEXT[cond]
    return [{"id": CONDITIONS[cond][0], "main": main, "description": desc,
             "icon": icon + ("d" if w.get("isDay", True) else "n")}]


def _owm_temp(temp_c, units):
    """Celsius -> the unit the request asked for (standard=Kelvin by default)."""
    if units == "metric":
        return temp_c
    if units == "imperial":
        return temp_c * 9.0 / 5.0 + 32
    return temp_c + 273.15


def _owm_units(request):
    from urllib.parse import parse_qs
    q = parse_qs(urlparse(getattr(request, "url", "")).query)
    return (q.get("units") or ["standard"])[0].lower()


def build_owm(cfg, units="standard"):
    w = cfg.get("weather", DEFAULTS["weather"])
    loc = cfg.get("location", DEFAULTS["location"])
    now = int(time.time())
    if w.get("isDay", True):
        sunrise, sunset = now - 21600, now + 21600   # dt within (sunrise,sunset) => day
    else:
        sunrise, sunset = now - 43200, now - 3600     # dt > sunset => night
    temp = _owm_temp(w.get("tempC", 20.56), units)
    return {
        "cod": 200,
        "coord": {"lat": loc.get("lat", 0), "lon": loc.get("lon", 0)},
        "weather": _owm_weather(cfg),
        "main": {"temp": temp, "feels_like": temp, "temp_min": temp - 3,
                 "temp_max": temp + 3, "pressure": 1015, "humidity": 50},
        "wind": {"speed": 3.0, "deg": 180},
        "clouds": {"all": 0},
        "sys": {"sunrise": sunrise, "sunset": sunset},
        "timezone": 0,
        "dt": now,
        "id": 0,
        "name": loc.get("name", ""),
    }


def build_owm_onecall(cfg, units="standard"):
    w = cfg.get("weather", DEFAULTS["weather"])
    loc = cfg.get("location", DEFAULTS["location"])
    now = int(time.time())
    t = lambda c: _owm_temp(c, units)
    base = w.get("tempC", 20.56)
    weather = _owm_weather(cfg)
    day = now - now % 86400 + 43200
    return {
        "lat": loc.get("lat", 0), "lon": loc.get("lon", 0),
        "timezone": "UTC", "timezone_offset": 0,
        "current": {
            "dt": now, "sunrise": now - 21600, "sunset": now + 21600,
            "temp": t(base), "feels_like": t(base), "pressure": 1015,
            "humidity": 50, "uvi": 0, "clouds": 0, "visibility": 10000,
            "wind_speed": 3.0, "wind_deg": 180, "weather": weather,
        },
        "hourly": [{
            "dt": now + 3600 * i, "temp": t(base), "feels_like": t(base),
            "pressure": 1015, "humidity": 50, "wind_speed": 3.0, "pop": 0,
            "weather": weather,
        } for i in range(1, 25)],
        "daily": [{
            "dt": day + 86400 * i, "sunrise": day + 86400 * i - 21600,
            "sunset": day + 86400 * i + 21600,
            "temp": {"day": t(base), "min": t(base - 3), "max": t(base + 3),
                     "night": t(base - 2), "eve": t(base), "morn": t(base - 1)},
            "feels_like": {"day": t(base), "night": t(base - 2),
                           "eve": t(base), "morn": t(base - 1)},
            "pressure": 1015, "humidity": 50, "wind_speed": 3.0, "pop": 0,
            "weather": weather,
        } for i in range(0, 7)],
    }


def build_owm_forecast(cfg, units="standard"):
    w = cfg.get("weather", DEFAULTS["weather"])
    loc = cfg.get("location", DEFAULTS["location"])
    now = int(time.time())
    temp = _owm_temp(w.get("tempC", 20.56), units)
    weather = _owm_weather(cfg)
    lst = [{
        "dt": now + 10800 * i,
        "main": {"temp": temp, "feels_like": temp, "temp_min": temp - 3,
                 "temp_max": temp + 3, "pressure": 1015, "humidity": 50},
        "weather": weather,
        "wind": {"speed": 3.0, "deg": 180},
        "dt_txt": time.strftime("%Y-%m-%d %H:%M:%S", time.gmtime(now + 10800 * i)),
    } for i in range(1, 9)]
    return {
        "cod": "200", "message": 0, "cnt": len(lst), "list": lst,
        "city": {"id": 0, "name": loc.get("name", ""),
                 "coord": {"lat": loc.get("lat", 0), "lon": loc.get("lon", 0)},
                 "country": "", "timezone": 0,
                 "sunrise": now - 21600, "sunset": now + 21600},
    }


def owm_payload(request, cfg):
    """Synthetic body for an api.openweathermap.org URL, or None to pass it
    through to the real network (e.g. /geo/ lookups)."""
    path = urlparse(getattr(request, "url", "")).path.rstrip("/").lower()
    units = _owm_units(request)
    if path == "/data/2.5/weather":
        return build_owm(cfg, units)
    if path in ("/data/3.0/onecall", "/data/2.5/onecall"):
        return build_owm_onecall(cfg, units)
    if path == "/data/2.5/forecast":
        return build_owm_forecast(cfg, units)
    return None


def build_weatherapi(cfg):
    w = cfg.get("weather", DEFAULTS["weather"])
    code = CONDITIONS.get(w.get("condition"), CONDITIONS["clear"])[1]
    temp_c = w.get("tempC", 20.56)
    is_day = 1 if w.get("isDay", True) else 0
    return {
        "current": {
            "temp_c": round(temp_c),
            "temp_f": _to_f(temp_c),
            "is_day": is_day,
            "condition": {"code": code, "text": ""},
        },
        "forecast": {"forecastday": [{
            "day": {
                "maxtemp_c": round(temp_c) + 3, "mintemp_c": round(temp_c) - 3,
                "maxtemp_f": _to_f(temp_c) + 5, "mintemp_f": _to_f(temp_c) - 5,
            },
            "astro": {"sunrise": "06:00 AM", "sunset": "08:00 PM"},
        }]},
    }


def _json_response(req, payload):
    from requests.models import Response
    r = Response()
    r.status_code = 200
    r.reason = "OK"
    r._content = json.dumps(payload).encode("utf-8")
    r._content_consumed = True
    r.encoding = "utf-8"
    r.url = getattr(req, "url", "")
    r.request = req
    r.headers["Content-Type"] = "application/json"
    return r


def _text_response(req, text):
    from requests.models import Response
    r = Response()
    r.status_code = 200
    r.reason = "OK"
    r._content = text.encode("utf-8")
    r._content_consumed = True
    r.encoding = "utf-8"
    r.url = getattr(req, "url", "")
    r.request = req
    r.headers["Content-Type"] = "text/plain"
    return r


# Default User-Agent for PebbleKit JS HTTP. `python-requests/x` is rejected by
# some weather APIs (MET Norway returns 403 "User-Agent header python-requests/...
# is not allowed, use a unique identifier"). Only replaces the library default; a
# UA the watchface sets itself is kept.
DEFAULT_UA = "PebbleStudio/3 pypkjs/2.0 (Pebble emulator)"

# The real requests.Session.send, captured by install(). Module-level (looked up at
# call time) so tests can stub the network.
_ORIG_SEND = None


def install_deferred(env_file):
    """Install the patches only once `requests.sessions` is imported.

    WHY: sitecustomize runs at interpreter startup. Importing requests there pulls
    in ssl/urllib3 BEFORE pypkjs runs gevent's monkey.patch_all(), so every real
    HTTPS request from PebbleKit JS then dies with RecursionError inside
    urllib3's create_urllib3_context (gevent#1016) — the XHR never completes.
    Deferring keeps startup import-free; by the time pypkjs imports requests,
    gevent has already patched ssl.
    """
    import sys
    sessions = sys.modules.get("requests.sessions")
    if sessions is not None:
        install(env_file, sessions)
        return

    class _AfterImport(object):
        """One-shot meta-path hook: run install() right after requests.sessions
        finishes executing."""

        def find_spec(self, name, path=None, target=None):
            if name != "requests.sessions":
                return None
            try:
                sys.meta_path.remove(self)
            except ValueError:
                pass
            spec = None
            for finder in sys.meta_path:
                fs = getattr(finder, "find_spec", None)
                if fs is None:
                    continue
                spec = fs(name, path, target)
                if spec is not None:
                    break
            if spec is None or spec.loader is None or not hasattr(spec.loader, "exec_module"):
                return spec
            orig_exec = spec.loader.exec_module

            def exec_module(module):
                orig_exec(module)
                try:
                    install(env_file, module)
                except Exception as e:  # never break the import
                    sys.stderr.write("pebble_studio_sim install failed: %r\n" % (e,))

            spec.loader.exec_module = exec_module
            return spec

    sys.meta_path.insert(0, _AfterImport())


def install(env_file, sessions=None):
    global _ORIG_SEND
    if sessions is None:
        import importlib
        sessions = importlib.import_module("requests.sessions")

    if getattr(sessions.Session.send, "_pebble_sim", False):
        return

    _ORIG_SEND = sessions.Session.send

    def send(self, request, **kwargs):
        try:
            ua = request.headers.get("User-Agent") or ""
            if not ua or ua.startswith("python-requests/"):
                request.headers["User-Agent"] = DEFAULT_UA
        except Exception:
            pass
        try:
            cfg = _read(env_file)
            if cfg.get("enabled", True):
                host = (urlparse(getattr(request, "url", "")).hostname or "").lower()
                if host == "api.openweathermap.org":
                    body = owm_payload(request, cfg)
                    if body is not None:
                        return _json_response(request, body)
                if host == "api.weatherapi.com":
                    return _json_response(request, build_weatherapi(cfg))
                if host == "api.ipify.org":
                    return _text_response(request, "8.8.8.8")
        except Exception:
            pass
        return _ORIG_SEND(self, request, **kwargs)

    send._pebble_sim = True
    sessions.Session.send = send

    try:
        import pygeoip
        _orig_rec = pygeoip.GeoIP.record_by_addr

        def record_by_addr(self, addr, *a, **k):
            try:
                cfg = _read(env_file)
                if cfg.get("enabled", True):
                    loc = cfg.get("location", DEFAULTS["location"])
                    return {
                        "latitude": loc.get("lat", 0.0),
                        "longitude": loc.get("lon", 0.0),
                        "city": loc.get("name", ""),
                        "country_code": "", "country_name": "",
                        "region_code": "", "region_name": "",
                        "time_zone": "", "metro_code": "",
                        "area_code": 0, "postal_code": "", "dma_code": 0,
                    }
            except Exception:
                pass
            return _orig_rec(self, addr, *a, **k)

        pygeoip.GeoIP.record_by_addr = record_by_addr
    except Exception:
        pass


if __name__ == "__main__":
    import sys
    if "--selftest" in sys.argv:
        owm = build_owm(DEFAULTS)
        wapi = build_weatherapi(DEFAULTS)
        assert owm["weather"][0]["id"] == 800, owm
        assert round(owm["main"]["temp"] - 273.15) == 21, owm
        assert owm["sys"]["sunrise"] < owm["dt"] < owm["sys"]["sunset"], owm
        assert wapi["current"]["condition"]["code"] == 1000, wapi
        assert wapi["current"]["temp_f"] == 69, wapi
        assert wapi["current"]["is_day"] == 1, wapi
        # night flips day/night markers
        night = dict(DEFAULTS, weather=dict(DEFAULTS["weather"], isDay=False))
        owm_n = build_owm(night)
        assert not (owm_n["sys"]["sunrise"] < owm_n["dt"] < owm_n["sys"]["sunset"]), owm_n
        assert build_weatherapi(night)["current"]["is_day"] == 0
        print("OK")
